@@ -1,7 +1,8 @@
 /// The daily quota of a plan.
 pub fn quota(plan: &str) -> Option<u32> {
-    match plan { "free" => Some(10), "pro" => Some(100), _ => None }
+    match plan { "free" => Some(10), "pro" => Some(200), _ => None }
 }

