+const RESET: &str = "00:00 UTC";
+const WINDOW_SECONDS: u64 = 86_400; // a long comment that goes on and on so that the line is wider than the pane is and must wrap
 fn main() {}
diff --git a/lib/quota.py b/lib/quota.py
new file mode 100644
--- /dev/null
+++ b/lib/quota.py
